/**
 * @description A message from the system.
 * @type object
 */
export type SystemMessageV2 = {
  role: 'system'
  content:
    | string
    | (ChatTextContent & {
        type: 'text'
      })[]
}

/**
 * @description Relevant information that could be used by the model to generate a more accurate reply.
 * The content of each document are generally short (should be under 300 words). Metadata should be used to provide additional information, both the key name and the value will be
 * passed to the model.
 *
 * @type object
 */
export type Document = {
  /**
   * @description A relevant document that the model can cite to generate a more accurate reply. Each document is a string-any dictionary.
   *
   * @type object
   */
  data: object
  /**
   * @description Unique identifier for this document which will be referenced in citations. If not provided an ID will be automatically generated.
   * @type string | undefined
   */
  id?: string
}

/**
 * @description Document content.
 * @type object
 */
export type DocumentContent = {
  type: 'document'
  /**
   * @description Relevant information that could be used by the model to generate a more accurate reply.
   * The content of each document are generally short (should be under 300 words). Metadata should be used to provide additional information, both the key name and the value will be
   * passed to the model.
   *
   * @type object
   */
  document: Document
}

/**
 * @description A content block which contains information about the content of a tool result
 */
export type ToolContent =
  | (ChatTextContent & {
      type: 'text'
    })
  | (DocumentContent & {
      type: 'document'
    })

/**
 * @description A message with Tool outputs.
 * @type object
 */
export type ToolMessageV2 = {
  role: 'tool'
  /**
   * @description The id of the associated tool call that has provided the given content
   * @type string
   */
  tool_call_id: string
  /**
   * @description Outputs from a tool. The content should formatted as a JSON object string, or a list of tool content blocks
   */
  content: string | ToolContent[]
}

/**
 * @description Represents a single message in the chat history from a given role.
 */
export type ChatMessageV2 =
  | (UserMessageV2 & {
      role: 'user'
    })
  | (AssistantMessageV2 & {
      role: 'assistant'
    })
  | (SystemMessageV2 & {
      role: 'system'
    })
  | (ToolMessageV2 & {
      role: 'tool'
    })

/**
 * @description A list of chat messages in chronological order, representing a conversation between the user and the model.
 *
 * Messages can be from `User`, `Assistant`, `Tool` and `System` roles. Learn more about messages and roles in [the Chat API guide](https://docs.cohere.com/v2/docs/chat-api).
 *
 * @type array
 */
export type ChatMessages = ChatMessageV2[]

