/**
 * @description A streamed event which signifies that the chat message has ended.
 */
export type ChatMessageEndEvent = ChatStreamEventType & {
  id?: string
  delta?: {
    /**
     * @description An error message if an error occurred during the generation.
     *
     * @type string | undefined
     */
    error?: string
    /**
     * @description The reason a chat request has finished.
     *
     * - **complete**: The model finished sending a complete message.
     * - **max_tokens**: The number of generated tokens exceeded the model's context length or the value specified via the `max_tokens` parameter.
     * - **stop_sequence**: One of the provided `stop_sequence` entries was reached in the model's generation.
     * - **tool_call**: The model generated a Tool Call and is expecting a Tool Message in return
     * - **error**: The generation failed due to an internal error
     * - **timeout**: The generation was stopped because it exceeded the allowed time limit.
     *
     * @type string | undefined
     */
    finish_reason?: ChatFinishReasonKey
    usage?: Usage
  }
}

/**
 * @description A streamed event which signifies that a stream has started.
 */
export type ChatMessageStartEvent = ChatStreamEventType & {
  /**
   * @description Unique identifier for the generated reply.
   * @type string | undefined
   */
  id?: string
  delta?: {
    message?: {
      /**
       * @description The role of the message.
       * @type string | undefined
       */
      role?: 'assistant'
    }
  }
}

export type ChatResponseV2 = {
  /**
   * @description Unique identifier for the generated reply. Useful for submitting feedback.
   * @type string
   */
  id: string
  /**
   * @description The reason a chat request has finished.
   *
   * - **complete**: The model finished sending a complete message.
   * - **max_tokens**: The number of generated tokens exceeded the model's context length or the value specified via the `max_tokens` parameter.
   * - **stop_sequence**: One of the provided `stop_sequence` entries was reached in the model's generation.
   * - **tool_call**: The model generated a Tool Call and is expecting a Tool Message in return
   * - **error**: The generation failed due to an internal error
   * - **timeout**: The generation was stopped because it exceeded the allowed time limit.
   *
   * @type string
   */
  finish_reason: ChatFinishReasonKey
  /**
   * @description A message from the assistant role can contain text and tool call information.
   * @type object
   */
  message: AssistantMessageResponse
  usage?: Usage
  logprobs?: LogprobItem[]
}

/**
 * @description A streamed event delta which signifies a delta in tool call arguments.
 */
export type ChatToolCallDeltaEvent = ChatStreamEventType & {
  index?: number
  delta?: {
    message?: {
      tool_calls?: {
        function?: {
          arguments?: string
        }
      }
    }
  }
}

/**
 * @description A streamed event delta which signifies a tool call has finished streaming.
 */
export type ChatToolCallEndEvent = ChatStreamEventType & {
  index?: number
}

/**
 * @description A streamed event delta which signifies a tool call has started streaming.
 */
export type ChatToolCallStartEvent = ChatStreamEventType & {
  index?: number
  delta?: {
    message?: {
      /**
       * @description An array of tool calls to be made.
       * @type object | undefined
       */
      tool_calls?: ToolCallV2
    }
  }
}

/**
 * @description A streamed event which contains a delta of tool plan text.
 */
export type ChatToolPlanDeltaEvent = ChatStreamEventType & {
  delta?: {
    message?: {
      tool_plan?: string
    }
  }
}

/**
 * @description StreamedChatResponse is returned in streaming mode (specified with `stream=True` in the request).
 */
export type StreamedChatResponseV2 =
  | (ChatMessageStartEvent & {
      type: 'message-start'
    })
  | (ChatContentStartEvent & {
      type: 'content-start'
    })
  | (ChatContentDeltaEvent & {
      type: 'content-delta'
    })
  | (ChatContentEndEvent & {
      type: 'content-end'
    })
  | (ChatToolPlanDeltaEvent & {
      type: 'tool-plan-delta'
    })
  | (ChatToolCallStartEvent & {
      type: 'tool-call-start'
    })
  | (ChatToolCallDeltaEvent & {
      type: 'tool-call-delta'
    })
  | (ChatToolCallEndEvent & {
      type: 'tool-call-end'
    })
  | (ChatMessageEndEvent & {
      type: 'message-end'
    })
  | (ChatDebugEvent & {
      type: 'debug'
    })

